<script setup>
import { AlertCircle, CheckCircle, Info, TriangleAlert, X } from 'lucide-vue-next'; import { watch } from 'vue'; import { useUiStore } from '@/stores/ui'; const ui = useUiStore(); const icons = { success: CheckCircle, error: AlertCircle, warning: TriangleAlert, info: Info }; const colors = { success: 'border-l-green-500 text-green-600', error: 'border-l-red-500 text-red-500', warning: 'border-l-amber-500 text-amber-600', info: 'border-l-blue-500 text-blue-500' }; const scheduled = new Set(); watch(() => ui.toasts, (toasts) => toasts.forEach((toast) => { if (!scheduled.has(toast.id)) { scheduled.add(toast.id); window.setTimeout(() => ui.removeToast(toast.id), toast.timeout || 4000); } }), { deep: true });
</script>
<template><div class="pointer-events-none fixed bottom-6 right-6 z-[100] flex max-w-[calc(100vw-3rem)] flex-col gap-2"><TransitionGroup name="toast"><div v-for="toast in ui.toasts" :key="toast.id" class="pointer-events-auto flex min-w-[280px] items-center gap-3 rounded-lg border border-l-4 border-[#E2E6EC] bg-white px-4 py-3 shadow-lg"><component :is="icons[toast.type] || icons.info" :size="16" :class="[colors[toast.type] || colors.info, 'shrink-0']" /><span class="flex-1 text-sm text-[#172033]">{{ toast.message }}</span><button aria-label="Tutup notifikasi" class="ml-1 text-[#667085] hover:text-[#172033]" @click="ui.removeToast(toast.id)"><X :size="14" /></button></div></TransitionGroup></div></template>
<style scoped>.toast-enter-active,.toast-leave-active{transition:all .15s}.toast-enter-from,.toast-leave-to{opacity:0;transform:translateY(8px)}</style>
